import sys,os,json,subprocess,hashlib,zipfile,time
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from v4_common import HERE,ROOT,save,sha,lock

def run():
 assert json.loads((HERE/'cycles/cycle3/AUDIT.json').read_text())['accepted']
 assert lock()==json.loads((HERE/'cycles/cycle3/SOURCE_LOCK.json').read_text())
 env=os.environ.copy()
 for k in ('OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS','NUMEXPR_NUM_THREADS'):env[k]='1'
 for script in ('ops/recover_snapshots.py','ops/reduce.py','ops/diagnose.py'):
  with open(HERE/'results'/f'{Path(script).stem}.log','w') as f:subprocess.run([sys.executable,'-u',str(HERE/script)],cwd=HERE,env=env,stdout=f,stderr=subprocess.STDOUT,check=True)
 summary=json.loads((HERE/'results/SUMMARY.json').read_text());diag=json.loads((HERE/'results/DIAGNOSIS.json').read_text());cfg=json.loads((HERE/'SPEC.json').read_text());pc=json.loads((HERE/'cycles/cycle3/POSITIVE_CONTROL.json').read_text())
 assert json.loads((HERE/'SNAPSHOT_AUDIT.json').read_text())['all_exact']
 assets=json.loads((ROOT/'minifly_v3_dev_20261020/cycles/cycle1/NATIVE_ASSET_AUDIT.json').read_text())['files']
 for name,want in assets.items():assert sha(ROOT/name)==want,name
 save(Path('PARENT_ASSET_AUDIT.json'),dict(accepted=True,files=assets,scope='Read-only native source identity, no historical experiment rerun'))
 receipts=[json.loads(p.read_text()) for p in sorted((HERE/'cycles/cycle3/jobs').glob('*/RECEIPT.json'))]
 import statistics
 table=[]
 for arm in ('B0','B1','B2','B3','B3_RANDOM','B3_N','B3_SH'):
  rows=[r for r in receipts if r['arm']==arm]
  mean=lambda phase,setname:statistics.mean(r['points'][phase][setname]['exact'] for r in rows)
  table.append(dict(arm=arm,acquisition_taught=mean('acquisition','taught'),rest_taught=mean('rest_before_replay','taught'),postreplay_taught=mean('rest_after_replay','taught'),postreplay_held=mean('rest_after_replay','held'),secondary_greedy_held=statistics.mean(r['secondary_greedy_held_exact'] for r in rows)))
 resource=summary['resource'];ledger=summary['ledger'];range0=summary['recorded_G0_range']
 save(Path('QUALIFICATION.json'),dict(status='THREE_CYCLES_COMPLETE_NO_ADVANCE',technical_cycles_completed=3,
  native_primitive_parity=True,corrected_teaching_direction_verified=True,zero_replay_and_checkpoint_checks_passed=True,
  independent_receipt_audit=True,G0_passed=False,G1_own_reply_positive_control_passed=pc['after']['exact']==1.,
  unseen_addition_improvement_demonstrated=False,formal_campaign_ready=False,large_P3_started=False,
  native_record_applications=ledger['native_record_applications'],oracle_code_extraction_presentations=ledger['G0_teacher_forced_oracle_record_presentations'],
  accepted_G1_jobs=14,correlated_histories=14,science_jobs_executed=0,automatic_adoption=False,
  reason='G0 coverage unmet; bounded native acquisition is not qualified at the declared warmup/exposure budget. These preflights do not reject arithmetic learning or the mechanism family in general.',
  source_lock_sha256=sha(HERE/'cycles/cycle3/SOURCE_LOCK.json'),final_audit_sha256=sha(HERE/'FINAL_AUDIT.json')))
 save(Path('MODEL_MANIFEST.json'),dict(version='MiniFly v4 audited engineering revision',received_design_commit=cfg['claude_commit'],
  value_kernel_parent='Qualified v3 batched native Full151 value equations',
  retained=['native gamma/alpha feedback, saturation, adaptation and signed W1-W0 write','native phenotype/genes and physiological readout'],
  changed=['generic raw-bit sequence input and nine bit/EOS output ports','learned stochastic boundary unit and finite generic segment buffers','shared sparse KC map with optional topographic prior','larger population sampled from native Q/T row distribution','optional recurrence-based alpha fast/slow allocation','stability-controlled warmup and bounded observed-record replay'],
  native_parent_equivalent_size_test=5177,coverage_sizes=cfg['sizes'],G1_size=65536,
  input_limit=256,output_limit=16,segment_slots=3,segment_item_limit=16,
  no_arithmetic_features_or_rules=True,no_attention_or_transformers=True,no_ELM_or_backprop=True,
  raw_bit_input_output=True,task_codebook_used_by_v4_ports=False,
  parent_birth_scaffold_imports_historical_codebook_asset=True,
  scaffold_boundary='Only canonical native birth/state construction is called; v4 never calls parent train/generate/logits or accesses its C16 targets. Raw-bit decoding and targets are in core_v4.py.',
  lineage_limit='B0 is the new bit/trace interface with native allocation; it is not an unchanged end-to-end Full151/C16 reference. Scaling and interface changes require their own behavioral qualification.'))
 header='# MiniFly v4 — audited design revision and three-cycle outcome\n\n**THREE_CYCLES_COMPLETE_NO_ADVANCE. Engineering only; no formal experiment or adoption.**\n\n'
 report='# MiniFly v4 three-cycle engineering report\n\n**Verdict: NO_ADVANCE — coverage and acquisition prerequisites are not qualified.** This is a bounded engineering result, not a scientific rejection of rule-free addition learning.\n\n'
 report+='Claude’s v4 memo at commit 190a26c was implemented as generic raw-bit IO, learned segment boundaries, position-local/random KC maps, native nine-channel value memory and recurrence-gated consolidation. No arithmetic parser, arithmetic-designated neurons, attention, Transformer, ELM answer model or backprop was introduced. Gradual warmup was retained.\n\n'
 report+='## Three cycles\n\n1. **Design/native audit:** native event parity at 5,177 cells, all-byte IO, content-identity confirmation, frozen queries and checkpoint/resume. Event parity did not by itself qualify the new teaching port.\n2. **Coverage preflight:** six registered 65,536/262,144-cell size/policy/wiring cases; 128 fitted and 64 held records each. The external linear readout fit training bytes at 100%, but held answer-byte correctness was '+f'{range0[0]:.2%}–{range0[1]:.2%}'+', with 0% teacher-forced exact held records. The 95% coverage gate failed. This fitted head is an evaluator-only diagnostic, not a learner or an impossibility bound.\n3. **Bounded learning sanity and revision:** corrected native-port teaching, replay limits and query chronology, then two technical worlds × seven arm/control histories, 64 fresh external records +8 replay applications each. The large P3/G2 run was not started.\n\n'
 report+='## Corrected native results\n\nMeans over two engineering worlds. Taught scores use the first 16 taught problems, held scores use 16 disjoint problems. Primary queries use a private frozen copy of the learned stochastic boundary policy.\n\n| Arm | Taught after acquisition | After rest | After replay | Unseen after replay |\n|---|---:|---:|---:|---:|\n'
 for row in table:report+=f"| {row['arm']} | {row['acquisition_taught']:.1%} | {row['rest_taught']:.1%} | {row['postreplay_taught']:.1%} | {row['postreplay_held']:.1%} |\n"
 report+='\nB0: new bit/trace interface with native allocation; B1: recurrence gate only; B2: segment/topographic map only; B3: both; B3_RANDOM: random wiring lesion; B3_N: no-write sensory history; B3_SH: shuffled-label history. B0 is not the old end-to-end C16 control. All histories share births and streams within a world; shuffled labels preserve answer lengths and clocks.\n\n'
 report+=f"The independent directional fixture reduced matched-control native residual loss from {pc['directional_native_loss_before']:.6f} to {pc['directional_native_loss_after']:.6f}. The separate 16-presentation arbitrary-byte control ended at {pc['after']['exact']:.1%} exact own reply. A correct update direction therefore does not establish usable acquisition at this dose.\n\n"
 report+='Recent-taught read-only checkpoint probes and consolidation diagnostics:\n\n'
 for row in diag['worlds']:report+=f"- World {row['world']}: recent-taught exact {row['recent_taught_postrest_replay']['exact']:.1%}; boundary probabilities {row['boundary_probability_min']:.6f}–{row['boundary_probability_max']:.6f}; warmup multiplier {row['warmup_a']:.4f}.\n"
 report+='\n## What the result does and does not establish\n\nThe correct teaching direction is verified, but the current short warmup does not qualify exact byte acquisition. Boundary learning remains close to its neutral policy; nonzero confirmation/slow weights are not proof of useful reusable structure. A recurrence gate can consolidate ordinary bit/format regularities as well as useful patterns. Its sigmoid also permits 0.899% slow allocation at q=0, so it is not a strict “nothing permanent before confirmation” rule.\n\nThe pre-learning G0 ordering is circular if useful segment codes require learned boundaries. A fit on untrained stochastic/neutral features does not reject the eventual learned representation. Conversely, increasing KC count fourfold did not meet G0 in these probes. Neither observation licenses a larger run or a claim of impossibility.\n\nCompared with v3, v4 changes input encoding, output ports, cell population, commitment, segmentation, arithmetic length and repetition policy. These tests do not isolate which change explains the difference from v3’s strong taught recall. Stability-controlled warmup and a small fresh-only dataset also differ from v3’s repeated facts. No arithmetic-specific repair or lowered exact-answer standard was used.\n\n'
 report+='## Preserved failures and exposure accounting\n\nThe first empty-set digest failure used four generic applications. A zero-replay slice bug used four preflight applications plus 64 external and 40 replay applications in an invalid B0 history. A reversed teaching coefficient was subsequently found by source-to-port audit; six complete wrong-sign histories and 16 whole records in a seventh were preserved as invalid, along with four preflight applications. A directional fixture then needed a matched passive-adaptation control; its four generic applications are also counted. Syntax/import/launch failures before training used zero records. None supports a model efficacy verdict. The corrected sign, replay boundary and passive chronology are tested in the final source.\n\n'
 report+=f"The ledger totals **{ledger['native_record_applications']:,} native full-record applications**, including all failed work and replay. Corrected G1 contributes 14 correlated histories and 1,008 applications (896 external, 112 replay). G0 separately used {ledger['G0_teacher_forced_oracle_record_presentations']:,} teacher-forced code-extraction record presentations and {ledger['G0_teacher_forced_target_events']:,} target positions, with no native learning. The combined presentation total is {ledger['all_native_plus_oracle_record_presentations']:,}; it is not a scientific sample count. Scientific records/jobs: **zero**. Partial native-event fixtures are listed separately.\n\n"
 report+='## Compute and limits\n\n'
 report+=f"Corrected accepted jobs recorded {resource['recorded_native_production_CPU_seconds']:.2f} production CPU seconds, {resource['recorded_primary_evaluation_CPU_seconds']:.2f} primary-evaluation CPU seconds, and {resource['accepted_job_phase_CPU_seconds']:.2f} full job-phase CPU seconds. G0 used {resource['G0_cycle_CPU_seconds']:.2f} CPU seconds. The corrected third cycle’s process peak RSS was {resource['corrected_cycle3_peak_RSS_bytes']/1024**2:.1f} MiB. One numerical thread was used; caffeinate followed the controller.\n\n"
 report+=resource['limitation']+' Global KC projection/top-k and query-state copies remain explicit prototype costs; sparse activity is not a sparse-compute claim. No end-to-end efficiency advantage is established.\n\n'
 report+='## Revised next prerequisite\n\nKeep the addition goal and generic architecture constraints. First qualify the new bit-output/native interface on bounded taught byte episodes under the declared gradual warmup, with matched native no-write controls. Then qualify boundary learning from the same observed raw addition stream, and run G0 on frozen **learned** codes with a new diagnostic split. Only after those prerequisites should consolidation’s benefit be compared at matched data and cost. A generic byte-prediction feedback arm may be designed separately; no delimiters, digit/place/carry features or arithmetic relations may be supplied. No such new training run was executed here.\n\nA future comparison should retain an explicit v3 anchor on a shared addition range and distinguish output-format acquisition from arithmetic transfer. Do not silently grow N, repeat the held set, change answer order or relax exact own-output scoring to manufacture progress.\n'
 (HERE/'REPORT.md').write_text(report)
 revised=header+(HERE/'design/EXPERIMENT.md').read_text()+'''\n\n## Final revision after the third cycle\n\nThe [engineering report](../minifly_v4_dev_20261020/REPORT.md), [qualification](../minifly_v4_dev_20261020/QUALIFICATION.json), and [exposure ledger](../minifly_v4_dev_20261020/TRAINING_LEDGER.json) are the executed status authority. All three cycles are complete; both the coverage prerequisite and exact own-reply acquisition remain unqualified at the tested budget. Native kernel/interface correctness, observed confirmation growth and external fitted-head memorization do not establish E3.\n\nThe next design must order its gates as (1) native raw-bit port acquisition under slow warmup; (2) learned boundary/representation qualification; (3) feature coverage on frozen learned codes; (4) consolidation benefit on matched addition samples and compute. G0 is empirical and cannot replace a causal learning result. B4/S0, broader arithmetic, trimming and evolution remain deferred; the full P3 campaign is not authorized or recommended.\n\nA generic extra feedback mechanism, such as prediction of each actually arriving byte in the same raw addition stream, can be a separately designed arm to address the weak delayed boundary signal. This is a proposal, not an implemented arithmetic aid. Any strict no-early-commitment variant must explicitly replace the soft sigmoid with a separately locked generic hurdle; it must not be silently substituted after seeing results. Preserve gradual warmup, ordinary answer order, all-256-byte IO, no arithmetic-designated state, no attention/Transformer/ELM/backprop, and exact own-output scoring.\n'''
 delivered=ROOT/'minifly_v4_design_20261020';delivered.mkdir(exist_ok=True);(delivered/'DESIGN.md').write_text(revised)
 # Link the source memo separately instead of pretending it is the audited revision.
 (delivered/'CLAUDE_RECEIVED.md').write_text((HERE/'design/CLAUDE_RECEIVED.md').read_text())
 (HERE/'cycles/cycle3/REVIEW.md').write_text('''# Third cycle review\n\nWrong-sign and replay-boundary histories are retained and excluded from efficacy. The final native port uses the pinned positive residual convention and passes a matched passive-event directional check. The independent reducer accepts all 14 corrected 72-application receipts, no-write state, exact-output reduction and matched clocks. The own-reply positive control and G0 gates remain unqualified. See REPORT.md for the measured results, caveats and revised ordering of prerequisites. No formal campaign, extra sample extension or adoption occurred.\n''')
 save(Path('SOURCE_LOCK.json'),dict(operative_files=lock(),source_unchanged_during_final_cycle=True,
  native_asset_certificate_sha256=sha(HERE/'PARENT_ASSET_AUDIT.json'),
  snapshot_audit_sha256=sha(HERE/'SNAPSHOT_AUDIT.json'),ops_files={str(p.relative_to(ROOT)):sha(p) for p in (HERE/'ops').glob('*.py')},delivered_design_sha256=sha(delivered/'DESIGN.md')))
 pointer=ROOT/'PROJECT_DOCUMENTS/CURRENT_ARITHMETIC_EXPERIMENT_DESIGN.json';d=json.loads(pointer.read_text());d['next_design'].update(status='THREE_CYCLES_COMPLETE_NO_ADVANCE',technical_cycles_executed=3,native_training_record_applications=1602,oracle_code_extraction_presentations=1152,science_jobs_executed=0,report=str(HERE/'REPORT.md'),design=str(delivered/'DESIGN.md'),qualification=str(HERE/'QUALIFICATION.json'),source_lock=str(HERE/'SOURCE_LOCK.json'),formal_campaign_ready=False,large_P3_started=False,launch_authorized=False,pilot_started=False,new_core_adopted=False,verdict=summary['verdict']);pointer.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
 save(Path('STATUS.json'),dict(status='THREE_CYCLES_COMPLETE_NO_ADVANCE',cycles_completed=3,native_record_applications=1602,G0_oracle_presentations=1152,scientific_records=0,active_workers=[],large_P3_started=False,automatic_adoption=False))
 # Self-contained dependency closure: exact current v4, pinned v3 native source/assets, parent native source.
 files=[p for p in HERE.rglob('*') if p.is_file() and not any(x in p.relative_to(HERE).parts for x in ('scratch','__pycache__')) and p.name not in ('RESULT_BUNDLE.zip','PACKAGE.json','BUNDLE_MANIFEST.json') and not p.name.endswith('.pending')]
 dep=ROOT/'minifly_v3_dev_20261020';files+=list(dep.glob('*.py'));files+=list((dep/'upstream').rglob('*'));files+=[ROOT/'minifly_a_v3/SOURCE_LOCK.json']+list((ROOT/'minifly_a_v3/src').glob('*.py'))+list(delivered.glob('*.md'))
 files=sorted(set(p for p in files if p.is_file() and '__pycache__' not in p.parts and 'scratch' not in p.relative_to(ROOT).parts))
 save(Path('BUNDLE_MANIFEST.json'),dict(schema='MINIFLY_V4_TECHNICAL_BUNDLE',files={str(p.relative_to(ROOT)):dict(sha256=sha(p),bytes=p.stat().st_size) for p in files},scientific_records=0,native_record_applications=1602,
  roles='Current corrected results, preserved invalid attempts explicitly labeled, exact source snapshots and native dependencies; historical assets are not observations.'))
 out=HERE/'RESULT_BUNDLE.zip'
 with zipfile.ZipFile(out,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=6) as z:
  for p in files+[HERE/'BUNDLE_MANIFEST.json']:z.write(p,str(p.relative_to(ROOT)))
 with zipfile.ZipFile(out) as z:assert z.testzip() is None;entries=len(z.infolist())
 save(Path('PACKAGE.json'),dict(completed=True,path=str(out),bytes=out.stat().st_size,sha256=sha(out),entries=entries,native_record_applications=1602,scientific_records=0,manifest_sha256=sha(HERE/'BUNDLE_MANIFEST.json')))
 print(json.dumps(dict(status='COMPLETE',verdict=summary['verdict'],native_record_applications=1602,report=str(HERE/'REPORT.md'),bundle_bytes=out.stat().st_size)),flush=True)

if __name__=='__main__':
 awake=subprocess.Popen(['/usr/bin/caffeinate','-i','-w',str(os.getpid())])
 try:run()
 finally:awake.terminate();awake.wait()
